CREATE TABLE "core"."assistant_action_stage_citations" (
    "stage_citation_id" text,
    "stage_id" text NOT NULL,
    "stage_item_id" text NOT NULL,
    "citation_order" bigint NOT NULL DEFAULT 0,
    "citation_type" text,
    "target_kind" text,
    "target_id" text,
    "workflow_id" text,
    "draft_id" text,
    "packet_id" text,
    "projection_item_id" text,
    "context_pack_id" text,
    "memory_node_id" text,
    "decision_id" text,
    "preference_id" text,
    "open_loop_id" text,
    "review_item_id" text,
    "claim_id" text,
    "citation_id" text,
    "feedback_id" text,
    "recommendation_id" text,
    "source_id" text,
    "source_ref" text,
    "source_root_key" text,
    "rel_path" text,
    "note_rel_path" text,
    "citation_label" text,
    "created_at" text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
    "metadata_json" text,
    "migration_run_id" uuid,
    "migration_source_table" text,
    "migration_source_schema_version" integer,
    "migration_natural_key_hash" text,
    CONSTRAINT "assistant_action_stage_citations_pkey" PRIMARY KEY ("stage_citation_id"),
    CONSTRAINT "assistant_action_stage_citations_ck1" CHECK (
        "target_id" IS NOT NULL OR "workflow_id" IS NOT NULL OR "draft_id" IS NOT NULL OR "packet_id" IS NOT NULL
        OR "projection_item_id" IS NOT NULL OR "context_pack_id" IS NOT NULL OR "memory_node_id" IS NOT NULL
        OR "decision_id" IS NOT NULL OR "preference_id" IS NOT NULL OR "open_loop_id" IS NOT NULL
        OR "review_item_id" IS NOT NULL OR "claim_id" IS NOT NULL OR "citation_id" IS NOT NULL
        OR "feedback_id" IS NOT NULL OR "recommendation_id" IS NOT NULL OR "source_id" IS NOT NULL
        OR "source_ref" IS NOT NULL OR "rel_path" IS NOT NULL OR "note_rel_path" IS NOT NULL
      )
);

CREATE TABLE "core"."assistant_action_stage_events" (
    "event_id" text,
    "stage_id" text NOT NULL,
