    "migration_run_id" uuid,
    "migration_source_table" text,
    "migration_source_schema_version" integer,
    "migration_natural_key_hash" text,
    CONSTRAINT "assistant_action_stage_events_pkey" PRIMARY KEY ("event_id"),
    CONSTRAINT "assistant_action_stage_events_event_type_ck1" CHECK ("event_type" IN ('created', 'staged', 'item_added', 'citation_added', 'superseded'))
);

CREATE TABLE "core"."assistant_action_stage_items" (
    "stage_item_id" text,
    "stage_id" text NOT NULL,
    "item_order" bigint NOT NULL DEFAULT 0,
    "action_kind" text NOT NULL,
    "staged_state" text NOT NULL DEFAULT 'candidate',
    "source_section" text,
    "title" text,
    "detail" text,
    "block_reason" text,
    "execution_status" text NOT NULL DEFAULT 'not_executed',
    "external_system" text NOT NULL DEFAULT 'none',
    "external_ref" text,
    "requires_operator_review" bigint NOT NULL DEFAULT 1,
    "target_kind" text,
    "target_id" text,
    "workflow_id" text,
    "draft_id" text,
    "packet_id" text,
    "projection_item_id" text,
    "context_pack_id" text,
    "memory_node_id" text,
    "decision_id" text,
    "preference_id" text,
    "open_loop_id" text,
    "review_item_id" text,
    "claim_id" text,
    "citation_id" text,
    "feedback_id" text,
    "recommendation_id" text,
    "source_id" text,
    "source_ref" text,
    "source_root_key" text,
    "rel_path" text,
    "note_rel_path" text,
    "review_state" text,
    "effective_state" text,
    "item_digest" text,
    "created_at" text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
    "metadata_json" text,
    "migration_run_id" uuid,
    "migration_source_table" text,
    "migration_source_schema_version" integer,
    "migration_natural_key_hash" text,
    CONSTRAINT "assistant_action_stage_items_pkey" PRIMARY KEY ("stage_item_id"),
    CONSTRAINT "assistant_action_stage_items_action_kind_ck1" CHECK ("action_kind" IN ('open_loop_follow_up', 'review_candidate', 'source_review', 'project_risk_review', 'information_gap_review', 'decision_review', 'preference_review', 'human_follow_up', 'unknown')),
    CONSTRAINT "assistant_action_stage_items_staged_state_ck2" CHECK ("staged_state" IN ('candidate', 'blocked')),
    CONSTRAINT "assistant_action_stage_items_execution_status_ck3" CHECK ("execution_status" = 'not_executed'),
    CONSTRAINT "assistant_action_stage_items_external_system_ck4" CHECK ("external_system" = 'none'),
    CONSTRAINT "assistant_action_stage_items_external_ref_ck5" CHECK ("external_ref" IS NULL),
    CONSTRAINT "assistant_action_stage_items_requires_operator_review_ck6" CHECK ("requires_operator_review" = 1),
    CONSTRAINT "assistant_action_stage_items_review_state_ck7" CHECK ("review_state" IS NULL OR "review_state" IN ('unreviewed', 'needs_review', 'operator_accepted', 'operator_rejected', 'deferred', 'not_required', 'stale', 'superseded')),
    CONSTRAINT "assistant_action_stage_items_effective_state_ck8" CHECK ("effective_state" IS NULL OR "effective_state" IN ('candidate', 'accepted', 'rejected', 'deferred', 'not_required', 'stale', 'superseded'))
);

CREATE TABLE "core"."assistant_action_stage_receipts" (
