CREATE TABLE "core"."assistant_action_stages" (
    "stage_id" text,
    "stage_type" text NOT NULL,
    "workflow_type" text,
    "workflow_id" text,
    "title" text,
    "status" text NOT NULL DEFAULT 'staged',
    "action_policy" text NOT NULL DEFAULT 'no_execution',
    "execution_policy" text NOT NULL DEFAULT 'staged_only',
    "workflow_policy" text NOT NULL DEFAULT 'staging_only',
    "review_policy" text NOT NULL DEFAULT 'preserve_review_state',
    "citation_policy" text NOT NULL DEFAULT 'preserve_citations',
    "source_policy" text NOT NULL DEFAULT 'use_existing_artifacts_only',
    "requires_operator_review" bigint NOT NULL DEFAULT 1,
    "created_by" text,
    "created_at" text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
    "updated_at" text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
    "request_digest" text,
    "source_context_digest" text,
    "input_digest" text,
    "output_digest" text,
    "stage_policy_json" text,
    "budget_json" text,
    "item_count" bigint NOT NULL DEFAULT 0,
    "blocked_count" bigint NOT NULL DEFAULT 0,
    "citation_count" bigint NOT NULL DEFAULT 0,
    "truncated" boolean NOT NULL DEFAULT false,
    "metadata_json" text,
    "migration_run_id" uuid,
    "migration_source_table" text,
    "migration_source_schema_version" integer,
    "migration_natural_key_hash" text,
    CONSTRAINT "assistant_action_stages_pkey" PRIMARY KEY ("stage_id"),
    CONSTRAINT "assistant_action_stages_stage_type_ck1" CHECK ("stage_type" IN ('daily_brief_actions', 'meeting_follow_ups', 'project_actions', 'open_loop_actions', 'review_follow_ups', 'mixed_actions', 'unknown')),
    CONSTRAINT "assistant_action_stages_status_ck2" CHECK ("status" IN ('draft', 'staged', 'superseded')),
    CONSTRAINT "assistant_action_stages_action_policy_ck3" CHECK ("action_policy" = 'no_execution'),
    CONSTRAINT "assistant_action_stages_execution_policy_ck4" CHECK ("execution_policy" = 'staged_only'),
    CONSTRAINT "assistant_action_stages_workflow_policy_ck5" CHECK ("workflow_policy" = 'staging_only'),
    CONSTRAINT "assistant_action_stages_review_policy_ck6" CHECK ("review_policy" = 'preserve_review_state'),
    CONSTRAINT "assistant_action_stages_citation_policy_ck7" CHECK ("citation_policy" = 'preserve_citations'),
    CONSTRAINT "assistant_action_stages_source_policy_ck8" CHECK ("source_policy" = 'use_existing_artifacts_only'),
    CONSTRAINT "assistant_action_stages_requires_operator_review_ck9" CHECK ("requires_operator_review" = 1),
