    CONSTRAINT "assistant_answer_draft_citations_target_kind_ck2" CHECK ("target_kind" IS NULL OR "target_kind" IN ('claim', 'enrichment_receipt', 'enrichment_review_item', 'context_pack', 'context_pack_item', 'memory_node', 'memory_mention', 'memory_compilation', 'decision', 'preference', 'open_loop', 'unknown')),
    CONSTRAINT "assistant_answer_draft_citations_confidence_ck3" CHECK ("confidence" IS NULL OR ("confidence" >= 0.0 AND "confidence" <= 1.0)),
    CONSTRAINT "assistant_answer_draft_citations_review_state_ck4" CHECK ("review_state" IS NULL OR "review_state" IN ('unreviewed', 'needs_review', 'operator_accepted', 'operator_rejected', 'deferred', 'not_required', 'stale', 'superseded')),
    CONSTRAINT "assistant_answer_draft_citations_effective_state_ck5" CHECK ("effective_state" IS NULL OR "effective_state" IN ('candidate', 'accepted', 'rejected', 'deferred', 'not_required', 'stale', 'superseded')),
    CONSTRAINT "assistant_answer_draft_citations_inclusion_state_ck6" CHECK ("inclusion_state" IS NULL OR "inclusion_state" IN ('trusted', 'candidate', 'excluded', 'stale', 'superseded', 'not_required', 'deferred', 'unknown')),
    CONSTRAINT "assistant_answer_draft_citations_ck7" CHECK ("packet_citation_id" IS NOT NULL
            OR "source_id" IS NOT NULL OR "note_rel_path" IS NOT NULL OR "claim_id" IS NOT NULL
            OR "receipt_id" IS NOT NULL OR "pack_id" IS NOT NULL OR "pack_item_id" IS NOT NULL
