    CONSTRAINT "source_structure_overrides_trust_tier_ck5" CHECK ("trust_tier" IS NULL OR "trust_tier" IN ('high', 'medium', 'low', 'generated', 'supplemental')),
    CONSTRAINT "source_structure_overrides_is_backup_mirror_ck6" CHECK ("is_backup_mirror" IS NULL OR "is_backup_mirror" IN (0,1)),
    CONSTRAINT "source_structure_overrides_is_generated_output_ck7" CHECK ("is_generated_output" IS NULL OR "is_generated_output" IN (0,1)),
    CONSTRAINT "source_structure_overrides_is_sensitive_ck8" CHECK ("is_sensitive" IS NULL OR "is_sensitive" IN (0,1)),
    CONSTRAINT "source_structure_overrides_active_ck9" CHECK ("active" IN (false,true))
);

